    ],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 15000;
  const lineDiscountA = 500;
  const afterLineDiscountA = 9500;
  const bulkDiscountA = 237.5;
  const lineDiscountB = 250;
  const totalDiscount = lineDiscountA + bulkDiscountA + lineDiscountB;
  assert.equal(totals.subtotal, 15000);
  assert.equal(totals.discount, 988);
});

test('bulk discount is 2.5% of the amount after line discount', () => {
