test('bulk discount applies at exactly 10 units', () => {
  const invoiceNine = {
    lines: [{ sku: 'ITEM', qty: 9, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
  };
  const invoiceTen = {
    lines: [{ sku: 'ITEM', qty: 10, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
  };
  const totalsNine = invoiceTotals(invoiceNine);
  const totalsTen = invoiceTotals(invoiceTen);
  assert.equal(totalsNine.discount, 0);
  assert.equal(totalsTen.discount, 250);
});

test('bulk discount with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { sku: 'VAT-21', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { sku: 'VAT-0', qty: 10, unitPrice: 1000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 20000;
  const bulkDiscount = 500;
  const vat = Math.round(9750 * 0.21);
  assert.equal(totals.discount, 500);
  assert.equal(totals.vat, vat);
});

